/* Ported from smartisanos.widget.SmoothSeekBar in Smartisan OS 8.5.3. */
package org.opensmartisanos.ui.widget;
import android.content.Context;import android.util.AttributeSet;import android.widget.SeekBar;
public class SmartisanSmoothSeekBar extends SeekBar {private static final long FRAME=15;private int target=-1,original=-1;private Runnable tick;public SmartisanSmoothSeekBar(Context c){this(c,null);}public SmartisanSmoothSeekBar(Context c,AttributeSet a){this(c,a,android.R.attr.seekBarStyle);}public SmartisanSmoothSeekBar(Context c,AttributeSet a,int s){this(c,a,s,0);}public SmartisanSmoothSeekBar(Context c,AttributeSet a,int s,int r){super(c,a,s,r);}public synchronized void setProgressSmooth(int value){if(value==target)return;stop();int delta=value-super.getProgress(),threshold=getMax()/20;if(Math.abs(delta)<threshold){super.setProgress(value);return;}target=value;original=super.getProgress();int duration=Math.abs(delta)*200/Math.max(1,getMax())+100;int steps=Math.max(1,duration/(int)FRAME);float step=delta/(float)steps;final int[] count={0};tick=()->{synchronized(this){if(target!=value||original<0)return;count[0]++;if(count[0]>=steps){super.setProgress(value);stop();}else{super.setProgress(original+(int)(step*count[0]));postDelayed(tick,FRAME);}}};post(tick);}@Override public synchronized void setProgress(int value){if(value!=target){stop();super.setProgress(value);}}@Override public synchronized int getProgress(){return target!=-1?target:super.getProgress();}private void stop(){if(tick!=null)removeCallbacks(tick);target=-1;original=-1;tick=null;}@Override protected void onDetachedFromWindow(){stop();super.onDetachedFromWindow();}}
